// Mechanism oracle only: actual fixed exported RequestBodyLimiter + Go decoder
// and readers, with controlled underlying Read sizes. This is not a fake RTC,
// public business API, worker callback, or replacement for the real HTTP probe.
package main
import("encoding/json";"errors";"io";"net/http";"net/http/httptest";"os";"strings";"github.com/livekit/livekit-server/pkg/service")
type readCall struct{Requested int `json:"requested"`;Returned int `json:"returned"`;EOF bool `json:"eof"`}
type traced struct{body []byte;pattern int;calls []readCall}
func(t *traced)Read(p []byte)(int,error){requested:=len(p);if len(t.body)==0{t.calls=append(t.calls,readCall{requested,0,true});return 0,io.EOF};n:=len(p);if n>t.pattern{n=t.pattern};if n>len(t.body){n=len(t.body)};copy(p,t.body[:n]);t.body=t.body[n:];t.calls=append(t.calls,readCall{requested,n,false});return n,nil}
func main(){enc:=json.NewEncoder(os.Stdout);for _,pattern:=range []int{1,13,512,4096}{for _,kind:=range []string{"json-prefix-trailing","json-value-too-large","protobuf-read-all","whip-inner-read-all"}{body:=[]byte(`{}`+strings.Repeat(" ",1024));if kind=="json-value-too-large"{body=[]byte(`{"names":["`+strings.Repeat("x",1024)+`"]}`)};reader:=&traced{body:body,pattern:pattern};req:=httptest.NewRequest(http.MethodPost,"http://owned.invalid/",io.NopCloser(reader));req.ContentLength=-1;w:=httptest.NewRecorder();entered:=false;received:=0;errText:="";errorLimit:=int64(0);service.NewRequestBodyLimiter(256).ServeHTTP(w,req,func(w http.ResponseWriter,r *http.Request){entered=true;var err error;switch kind{case "json-prefix-trailing","json-value-too-large":var raw json.RawMessage;err=json.NewDecoder(r.Body).Decode(&raw);received=len(raw);case "protobuf-read-all":var n int64;n,err=io.Copy(io.Discard,r.Body);received=int(n);case "whip-inner-read-all":var bytes []byte;bytes,err=io.ReadAll(http.MaxBytesReader(w,r.Body,http.DefaultMaxHeaderBytes));received=len(bytes)};if err!=nil{errText=err.Error();var maxErr *http.MaxBytesError;if errors.As(err,&maxErr){errorLimit=maxErr.Limit}}});if err:=enc.Encode(map[string]any{"operation":kind,"configured_limit":256,"declared_length":-1,"source_body_bytes":len(body),"controlled_underlying_read_max":pattern,"next_entered":entered,"decoded_or_received_bytes":received,"error":errText,"actual_max_bytes_error_limit":errorLimit,"actual_read_calls":reader.calls});err!=nil{panic(err)}}}}
